import "./creator-adoption-commit.js";

import { consumeCreatorAdoptionPublish, consumeCreatorAdoptionStage } from "./internal/creator-adoption-stage.js";

/**
 * Durably completes one authenticated successor without publishing its AHE head.
 * @param input - Exact genuine close handle and owner-bound adoption intent.
 * @returns Opaque staged custody or a typed fail-closed result.
 */
export function stageCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
	return consumeCreatorAdoptionStage(input);
}

/**
 * Publishes one owner-bound staged successor through the exact AHE head CAS.
 * @param input - Exact staged capability and genuine close handle.
 * @returns Existing prepared-activation custody or a typed fail-closed result.
 */
export function publishStagedCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
	return consumeCreatorAdoptionPublish(input);
}
=====RECOVER=====
import "./creator-adoption.js";

import {
	consumeCreatorAdoptionPendingRecovery,
	type CreatorAdoptionPendingRecoveryInput,
} from "./internal/creator-adoption-recover.js";

const INPUT_KEYS = Object.freeze([
	"authenticationProfile",
	"catalog",
	"detachedSignature",
	"exactCanonicalAnchorPreimageBytes",
	"exactCanonicalParametersCarrierBytes",
	"expectedNextRoomHead",
	"expectedPreviousRoomHead",
	"pinnedGenesisAnchorDigest",
	"snapshotDeclaration",
	"snapshotStore",
	"store",
]);

function capture(value: unknown): CreatorAdoptionPendingRecoveryInput | undefined {
	try {
		if (value === null || typeof value !== "object" || Object.getPrototypeOf(value) !== Object.prototype) {
			return undefined;
		}
		const keys = Reflect.ownKeys(value);
		if (keys.length !== INPUT_KEYS.length || keys.some((key) => typeof key !== "string" || !INPUT_KEYS.includes(key))) {
			return undefined;
		}
		const output: Record<string, unknown> = Object.create(null) as Record<string, unknown>;
		for (const key of INPUT_KEYS) {
			const descriptor = Object.getOwnPropertyDescriptor(value, key);
			if (descriptor === undefined || descriptor.enumerable !== true || !("value" in descriptor)) return undefined;
			output[key] = descriptor.value;
		}
		return output as unknown as CreatorAdoptionPendingRecoveryInput;
	} catch {
		return undefined;
	}
}

/**
 * Authenticates and publishes a provider-selected pending successor without live activation.
 * @param input - Exact copied provider heads, genesis carriers, snapshot owners and AHE store.
 * @returns Published stable room head or a typed fail-closed result.
 */
export function recoverPendingCreatorSuccessorAdoption(input: unknown): Promise<Readonly<Record<string, unknown>>> {
	const captured = capture(input);
	return captured === undefined
		? Promise.resolve(
				Object.freeze({
					detail: "creator adoption pending recovery input is invalid",
					kind: "malformed-input",
					ok: false,
				})
			)
		: consumeCreatorAdoptionPendingRecovery(captured);
}
=====INTERNAL-STAGE=====
type Result = Readonly<Record<string, unknown>>;
type StageOwner = (input: unknown) => Promise<Result>;

let publishOwner: StageOwner | undefined;
let stageOwner: StageOwner | undefined;

/**
 * Installs the sole private durable-stage owner.
 * @param owner - Authenticated stage kernel.
 * @returns Whether the owner was installed.
 */
export function installCreatorAdoptionStage(owner: StageOwner): boolean {
	if (stageOwner !== undefined) return false;
	stageOwner = owner;
	return true;
}

/**
 * Installs the sole private staged-publication owner.
 * @param owner - Authenticated head-publication kernel.
 * @returns Whether the owner was installed.
 */
export function installCreatorAdoptionPublish(owner: StageOwner): boolean {
	if (publishOwner !== undefined) return false;
	publishOwner = owner;
	return true;
}

/**
 * Executes the installed private durable-stage owner.
 * @param input - Exact public stage input.
 * @returns Frozen stage result.
 */
export function consumeCreatorAdoptionStage(input: unknown): Promise<Result> {
	return stageOwner === undefined
		? Promise.resolve(
				Object.freeze({
					detail: "creator adoption stage owner is unavailable",
					kind: "internal-invariant",
					ok: false,
				})
			)
		: stageOwner(input);
}

/**
 * Executes the installed private staged-publication owner.
 * @param input - Exact public publication input.
 * @returns Frozen publication result.
 */
export function consumeCreatorAdoptionPublish(input: unknown): Promise<Result> {
	return publishOwner === undefined
		? Promise.resolve(
				Object.freeze({
					detail: "creator adoption publish owner is unavailable",
					kind: "internal-invariant",
					ok: false,
				})
			)
		: publishOwner(input);
}
=====INTERNAL-RECOVER=====
import type { TrustedBlueprintCatalog } from "@ts-drp/blueprint-catalog";
import type { AheDurableStore } from "@ts-drp/storage";
import type {
	SnapshotQuarantineDeclaration,
	SnapshotQuarantineStore,
	SnapshotVerificationReceipt,
} from "@ts-drp/storage/snapshot-transfer";

export interface CreatorAdoptionRoomHead {
	readonly currentAnchorDigest: string;
	readonly epoch: number;
	readonly objectId: string;
}

export interface CreatorAdoptionPendingRecoveryInput {
	readonly authenticationProfile: "creator-only";
	readonly catalog: TrustedBlueprintCatalog;
	readonly detachedSignature: Uint8Array;
	readonly exactCanonicalAnchorPreimageBytes: Uint8Array;
	readonly exactCanonicalParametersCarrierBytes: Uint8Array;
	readonly expectedNextRoomHead: CreatorAdoptionRoomHead;
	readonly expectedPreviousRoomHead: CreatorAdoptionRoomHead;
	readonly pinnedGenesisAnchorDigest: string;
	readonly snapshotDeclaration: SnapshotQuarantineDeclaration;
	readonly snapshotStore: SnapshotQuarantineStore<SnapshotVerificationReceipt>;
	readonly store: AheDurableStore;
}

export type CreatorAdoptionPendingRecoveryResult =
	| Readonly<{
			readonly head: CreatorAdoptionRoomHead;
			readonly lifecycle: "successor-published";
			readonly ok: true;
			readonly recovery: "active-new";
	  }>
	| Readonly<{ readonly detail: string; readonly kind: string; readonly ok: false }>;

type RecoveryOwner = (input: CreatorAdoptionPendingRecoveryInput) => Promise<CreatorAdoptionPendingRecoveryResult>;

let owner: RecoveryOwner | undefined;

/**
 * Installs the sole private non-activating pending-recovery owner.
 * @param candidate - Authenticated durable recovery kernel.
 * @returns Whether the owner was installed.
 */
export function installCreatorAdoptionPendingRecovery(candidate: RecoveryOwner): boolean {
	if (owner !== undefined) return false;
	owner = candidate;
	return true;
}

/**
 * Executes the installed private non-activating recovery owner.
 * @param input - Exact copied provider heads and durable authentication carriers.
 * @returns Published room head or typed fail-closed result.
 */
export function consumeCreatorAdoptionPendingRecovery(
	input: CreatorAdoptionPendingRecoveryInput
): Promise<CreatorAdoptionPendingRecoveryResult> {
	return owner === undefined
		? Promise.resolve(
				Object.freeze({
					detail: "creator adoption pending recovery owner is unavailable",
					kind: "internal-invariant",
					ok: false,
				})
			)
		: owner(input);
}

