140	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
141		return left.byteLength === right.byteLength && left.every((byte, index) => byte === right[index]);
142	}
143	
144	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
145		return left.byteLength === right.byteLength && left.digest === right.digest;
146	}
147	
148	function sameClosure(left: readonly GenerationRef[], right: readonly GenerationRef[]): boolean {
149		return left.length === right.length && left.every((ref, index) => sameRef(ref, right[index] as GenerationRef));
150	}
151	
152	function sameHead(left: PresentHead, right: PresentHead): boolean {
153		return (
154			left.closureDigest === right.closureDigest &&
155			left.generationId === right.generationId &&
156			left.objectId === right.objectId &&
157			left.revision === right.revision
158		);
159	}
160	
161	function canonicalRecord(bytes: Uint8Array): Readonly<Record<string, unknown>> | undefined {
162		try {
163			const decoded = decodeCanonical(bytes);
164			return record(decoded) && sameBytes(encodeCanonical(decoded), bytes) ? decoded : undefined;
165		} catch {
166			return undefined;
167		}
168	}
169	
170	function exactClosureDigest(references: readonly GenerationRef[], expected: string): boolean {
171		const digested = digestClosure(references);
172		return digested.ok && digested.value === expected;
173	}
