175	async function readLineage(
176		store: AheDurableStore,
177		objectId: SealedAdoptionFacts["objectId"]
178	): Promise<readonly GenerationRecord[] | undefined> {
179		const output: GenerationRecord[] = [];
180		const cursors = new Set<GenerationPageCursor>();
181		let cursor: GenerationPageCursor | undefined;
182		for (;;) {
183			const result = await store.readGenerationPage({
184				...(cursor === undefined ? {} : { cursor }),
185				limit: 128,
186				objectId,
187			});
188			if (!result.ok || (result.value.generations.length === 0 && result.value.nextCursor !== null)) return undefined;
189			output.push(...result.value.generations);
190			if (result.value.nextCursor === null) return Object.freeze(output);
191			if (cursors.has(result.value.nextCursor)) return undefined;
192			cursors.add(result.value.nextCursor);
193			cursor = result.value.nextCursor;
194		}
195	}
196	
197	async function loadClosure(
198		store: AheDurableStore,
199		references: readonly GenerationRef[]
200	): Promise<readonly Candidate[] | undefined> {
201		const candidates: Candidate[] = [];
202		for (const ref of references) {
203			const loaded = await store.getBlob(ref.digest);
204			if (!loaded.ok || loaded.value === null || loaded.value.byteLength !== ref.byteLength) return undefined;
205			const digest = digestBlob(loaded.value);
206			if (!digest.ok || digest.value !== ref.digest) return undefined;
207			candidates.push(Object.freeze({ bytes: Uint8Array.from(loaded.value), ref: Object.freeze({ ...ref }) }));
208		}
209		return Object.freeze(candidates);
210	}
211	
212	function candidateBytes(candidates: readonly Candidate[], ref: GenerationRef): Uint8Array | undefined {
213		return candidates.find((candidate) => sameRef(candidate.ref, ref))?.bytes;
214	}
215	
216	function validLineage(
217		generations: readonly GenerationRecord[],
218		facts: SealedAdoptionFacts,
219		material: CreatorAdoptionIntentMaterial,
220		activeHead: PresentHead,
221		activeIsCandidate: boolean
222	): boolean {
223		const byId = new Map(generations.map((generation) => [generation.generationId, generation]));
224		if (byId.size !== generations.length) return false;
225		const current = byId.get(facts.currentHead.generationId);
226		const pending = byId.get(facts.proposedHead.generationId);
227		const active = byId.get(activeHead.generationId);
228		if (
229			current === undefined ||
230			pending === undefined ||
231			active === undefined ||
232			current.state !== "Superseded" ||
233			!sameClosure(current.closure, facts.currentReferences) ||
234			pending.baseExpectedHead.kind !== "present" ||
235			!sameHead(pending.baseExpectedHead, facts.currentHead) ||
236			!sameClosure(pending.closure, facts.proposedReferences) ||
237			facts.proposedHead.revision !== facts.currentHead.revision + 1
238		) {
239			return false;
240		}
241		if (activeIsCandidate) {
242			if (
243				pending.state !== "Superseded" ||
244				active.state !== "Adopted" ||
245				active.baseExpectedHead.kind !== "present" ||
246				!sameHead(active.baseExpectedHead, facts.proposedHead) ||
247				!sameClosure(active.closure, material.candidateReferences)
248			) {
249				return false;
250			}
251		} else if (pending.state !== "Adopted" || active !== pending) {
252			return false;
253		}
254		for (const generation of generations) {
255			if (new Set(generation.closure.map(({ digest }) => digest)).size !== generation.closure.length) return false;
256			if (
257				generation.baseExpectedHead.kind === "present" &&
258				(generation.baseExpectedHead.generationId === generation.generationId ||
259					!byId.has(generation.baseExpectedHead.generationId))
260			) {
261				return false;
262			}
263		}
264		return true;
265	}
266	
267	function validStagedLineage(
268		generations: readonly GenerationRecord[],
269		facts: SealedAdoptionFacts,
270		material: CreatorAdoptionIntentMaterial
271	): boolean {
272		const byId = new Map(generations.map((generation) => [generation.generationId, generation]));
273		if (byId.size !== generations.length) return false;
274		const current = byId.get(facts.currentHead.generationId);
275		const pending = byId.get(facts.proposedHead.generationId);
276		const staged = byId.get(material.generationId);
277		if (
278			current === undefined ||
279			pending === undefined ||
280			staged === undefined ||
281			current.state !== "Superseded" ||
282			pending.state !== "Adopted" ||
283			staged.state !== "Complete" ||
284			!sameClosure(current.closure, facts.currentReferences) ||
285			pending.baseExpectedHead.kind !== "present" ||
286			!sameHead(pending.baseExpectedHead, facts.currentHead) ||
287			!sameClosure(pending.closure, facts.proposedReferences) ||
288			staged.baseExpectedHead.kind !== "present" ||
289			!sameHead(staged.baseExpectedHead, material.pendingHead) ||
290			!sameClosure(staged.closure, material.candidateReferences) ||
291			facts.proposedHead.revision !== facts.currentHead.revision + 1
292		) {
293			return false;
294		}
295		for (const generation of generations) {
296			if (new Set(generation.closure.map(({ digest }) => digest)).size !== generation.closure.length) return false;
297			if (
298				generation.baseExpectedHead.kind === "present" &&
299				(generation.baseExpectedHead.generationId === generation.generationId ||
300					!byId.has(generation.baseExpectedHead.generationId))
301			) {
302				return false;
303			}
304		}
305		return true;
306	}
307	
308	function validProjection(material: CreatorAdoptionIntentMaterial): Readonly<Record<string, unknown>> | undefined {
309		const descriptor = canonicalRecord(material.exactCanonicalProjectionBytes);
310		if (descriptor?.kind !== "v3-live-generation-2") return undefined;
311		const digest = digestBlob(material.exactCanonicalProjectionBytes);
312		if (!digest.ok) return undefined;
313		const projectionRef = Object.freeze({
314			byteLength: material.exactCanonicalProjectionBytes.byteLength,
315			digest: digest.value,
316		});
317		const predecessorAclDigest = digestBlob(material.activation.predecessorExactCanonicalLatchedAclBytes);
318		if (!predecessorAclDigest.ok) return undefined;
319		const predecessorAclRef = Object.freeze({
320			byteLength: material.activation.predecessorExactCanonicalLatchedAclBytes.byteLength,
321			digest: predecessorAclDigest.value,
322		});
323		const retained = material.pendingReferences.filter((ref) => !sameRef(ref, material.predecessorLiveRef));
324		const derived = Object.freeze(
325			[
326				...retained,
327				projectionRef,
328				...(retained.some((ref) => sameRef(ref, predecessorAclRef)) ? [] : [predecessorAclRef]),
329			].sort((left, right) => (left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0))
330		);
331		return material.pendingReferences.filter((ref) => sameRef(ref, material.predecessorLiveRef)).length === 1 &&
332			new Set(derived.map(({ digest: value }) => value)).size === derived.length &&
333			sameClosure(derived, material.candidateReferences)
334			? Object.freeze(descriptor)
335			: undefined;
336	}
