338	function validTrustChain(
339		facts: SealedAdoptionFacts,
340		currentCandidates: readonly Candidate[],
341		pendingCandidates: readonly Candidate[]
342	): boolean {
343		const cutBytes = candidateBytes(pendingCandidates, facts.closeResult.cutValueRef);
344		const commitBytes = candidateBytes(pendingCandidates, facts.closeResult.commitQcRef);
345		const successorTrustBytes = candidateBytes(pendingCandidates, facts.closeResult.successorTrustRef);
346		const currentTrustBytes = candidateBytes(currentCandidates, facts.closeResult.currentTrustRef);
347		if (
348			cutBytes === undefined ||
349			commitBytes === undefined ||
350			successorTrustBytes === undefined ||
351			currentTrustBytes === undefined
352		) {
353			return false;
354		}
355		const opened = openCreatorSuccessorTrust({
356			currentTrust: facts.currentTrust,
357			exactCanonicalCommitQcBytes: commitBytes,
358			exactCanonicalCutValueBytes: cutBytes,
359			exactCanonicalTrustStateRecordBytes: successorTrustBytes,
360		});
361		if (
362			!opened.ok ||
363			opened.trust.currentAnchorDigest !== facts.closeResult.successorAnchorDigest ||
364			opened.trust.currentEpoch !== facts.closeResult.successorEpoch
365		) {
366			return false;
367		}
368		return inspectCreatorTrustAdvance({
369			current: { candidates: currentCandidates, closure: facts.currentReferences },
370			proofRefs: [facts.closeResult.cutValueRef, facts.closeResult.commitQcRef],
371			proposed: { candidates: pendingCandidates, closure: facts.proposedReferences },
372		}).ok;
373	}
