375	async function authenticatedTerminal(
376		facts: SealedAdoptionFacts,
377		material: CreatorAdoptionIntentMaterial
378	): Promise<Terminal> {
379		try {
380			if (
381				!sameHead(material.pendingHead, facts.proposedHead) ||
382				!sameClosure(material.pendingReferences, facts.proposedReferences) ||
383				material.pendingHead.objectId !== facts.objectId
384			) {
385				return Object.freeze({ kind: "chain-invalid" });
386			}
387			const recovered = await facts.store.recoverActiveGeneration(facts.objectId);
388			if (!recovered.ok || recovered.value.kind !== "active") {
389				return Object.freeze({ kind: "recovery-failed" });
390			}
391			const active = recovered.value;
392			const pending = sameHead(active.head, material.pendingHead);
393			const candidateDigest = digestClosure(material.candidateReferences);
394			const candidate =
395				candidateDigest.ok &&
396				active.head.objectId === material.pendingHead.objectId &&
397				active.head.revision === material.pendingHead.revision + 1 &&
398				active.head.closureDigest === candidateDigest.value &&
399				active.adoptedGeneration.state === "Adopted" &&
400				sameClosure(active.references, material.candidateReferences) &&
401				sameClosure(active.adoptedGeneration.closure, material.candidateReferences);
402			if (!pending && !candidate) return Object.freeze({ kind: "stale-head" });
403			if (
404				active.adoptedGeneration.state !== "Adopted" ||
405				!sameClosure(active.references, pending ? material.pendingReferences : material.candidateReferences) ||
406				!sameClosure(
407					active.adoptedGeneration.closure,
408					pending ? material.pendingReferences : material.candidateReferences
409				) ||
410				!exactClosureDigest(active.references, active.head.closureDigest)
411			) {
412				return Object.freeze({ kind: "chain-invalid" });
413			}
414			const [generations, currentCandidates, pendingCandidates, activeCandidates] = await Promise.all([
415				readLineage(facts.store, facts.objectId),
416				loadClosure(facts.store, facts.currentReferences),
417				loadClosure(facts.store, facts.proposedReferences),
418				loadClosure(facts.store, pending ? material.pendingReferences : material.candidateReferences),
419			]);
420			const descriptor = validProjection(material);
421			if (
422				generations === undefined ||
423				currentCandidates === undefined ||
424				pendingCandidates === undefined ||
425				activeCandidates === undefined ||
426				descriptor === undefined ||
427				!validLineage(generations, facts, material, active.head, candidate) ||
428				!validTrustChain(facts, currentCandidates, pendingCandidates)
429			) {
430				return Object.freeze({ kind: "chain-invalid" });
431			}
432			const predecessor = currentCandidates.filter(
433				({ bytes, ref }) =>
434					sameRef(ref, material.predecessorLiveRef) && canonicalRecord(bytes)?.kind === "v3-live-generation-1"
435			);
436			return predecessor.length === 1
437				? Object.freeze({ head: Object.freeze({ ...active.head }), kind: candidate ? "active-new" : "pending-old" })
438				: Object.freeze({ kind: "chain-invalid" });
439		} catch {
440			return Object.freeze({ kind: "recovery-failed" });
441		}
442	}
443	
444	async function authenticatedStaged(
445		facts: SealedAdoptionFacts,
446		material: CreatorAdoptionIntentMaterial
447	): Promise<StagedTerminal> {
448		try {
449			if (
450				!sameHead(material.pendingHead, facts.proposedHead) ||
451				!sameClosure(material.pendingReferences, facts.proposedReferences) ||
452				material.pendingHead.objectId !== facts.objectId
453			) {
454				return Object.freeze({ kind: "chain-invalid" });
455			}
456			const recovered = await facts.store.recoverActiveGeneration(facts.objectId);
457			if (!recovered.ok || recovered.value.kind !== "active") {
458				return Object.freeze({ kind: "recovery-failed" });
459			}
460			const active = recovered.value;
461			if (!sameHead(active.head, material.pendingHead)) return Object.freeze({ kind: "stale-head" });
462			if (
463				active.adoptedGeneration.state !== "Adopted" ||
464				!sameClosure(active.references, material.pendingReferences) ||
465				!sameClosure(active.adoptedGeneration.closure, material.pendingReferences) ||
466				!exactClosureDigest(active.references, active.head.closureDigest)
467			) {
468				return Object.freeze({ kind: "chain-invalid" });
469			}
470			const [generations, currentCandidates, pendingCandidates, stagedCandidates] = await Promise.all([
471				readLineage(facts.store, facts.objectId),
472				loadClosure(facts.store, facts.currentReferences),
473				loadClosure(facts.store, facts.proposedReferences),
474				loadClosure(facts.store, material.candidateReferences),
475			]);
476			const descriptor = validProjection(material);
477			if (
478				generations === undefined ||
479				currentCandidates === undefined ||
480				pendingCandidates === undefined ||
481				stagedCandidates === undefined ||
482				descriptor === undefined ||
483				!validStagedLineage(generations, facts, material) ||
484				!validTrustChain(facts, currentCandidates, pendingCandidates)
485			) {
486				return Object.freeze({ kind: "pending-old" });
487			}
488			const projection = stagedCandidates.filter(({ bytes }) => sameBytes(bytes, material.exactCanonicalProjectionBytes));
489			const predecessor = currentCandidates.filter(
490				({ bytes, ref }) =>
491					sameRef(ref, material.predecessorLiveRef) && canonicalRecord(bytes)?.kind === "v3-live-generation-1"
492			);
493			return projection.length === 1 && predecessor.length === 1
494				? Object.freeze({ kind: "staged" })
495				: Object.freeze({ kind: "chain-invalid" });
496		} catch {
497			return Object.freeze({ kind: "recovery-failed" });
498		}
499	}
500	
501	function successfulMutation(result: unknown): boolean {
502		return record(result) && result.ok === true && Object.hasOwn(result, "value");
503	}
504	
505	async function stageCandidate(facts: SealedAdoptionFacts, material: CreatorAdoptionIntentMaterial): Promise<void> {
506		const scope = Object.freeze({ generationId: material.generationId, objectId: facts.objectId });
507		if (
508			!successfulMutation(
509				await facts.store.beginGeneration({
510					...scope,
511					baseExpectedHead: material.pendingHead,
512					closure: material.candidateReferences,
513				})
514			)
515		) {
516			throw new TypeError("creator successor begin failed");
517		}
518		const projectionDigest = digestBlob(material.exactCanonicalProjectionBytes);
519		if (
520			!projectionDigest.ok ||
521			!successfulMutation(
522				await facts.store.putCachedBlob({
523					...scope,
524					bytes: material.exactCanonicalProjectionBytes,
525					digest: projectionDigest.value,
526				})
527			)
528		) {
529			throw new TypeError("creator successor projection cache failed");
530		}
531		const predecessorAclBytes = material.activation.predecessorExactCanonicalLatchedAclBytes;
532		const predecessorAclDigest = digestBlob(predecessorAclBytes);
533		if (
534			!predecessorAclDigest.ok ||
535			!successfulMutation(
536				await facts.store.putCachedBlob({
537					...scope,
538					bytes: predecessorAclBytes,
539					digest: predecessorAclDigest.value,
540				})
541			)
542		) {
543			throw new TypeError("creator predecessor ACL cache failed");
544		}
545		for (const ref of material.candidateReferences) {
546			if (!successfulMutation(await facts.store.promoteReference({ ...scope, digest: ref.digest }))) {
547				throw new TypeError("creator successor promotion failed");
548			}
549		}
550		if (!successfulMutation(await facts.store.completeGeneration(scope))) {
551			throw new TypeError("creator successor completion failed");
552		}
553	}
554	
555	async function publishCandidate(facts: SealedAdoptionFacts, material: CreatorAdoptionIntentMaterial): Promise<void> {
556		const scope = Object.freeze({ generationId: material.generationId, objectId: facts.objectId });
557		if (
558			!successfulMutation(
559				await facts.store.swapHead({
560					...scope,
561					expectedHead: material.pendingHead,
562				})
563			)
564		) {
565			throw new TypeError("creator successor head swap failed");
566		}
567	}
