569	function success(
570		handle: object,
571		material: CreatorAdoptionIntentMaterial,
572		descriptor: Readonly<Record<string, unknown>>,
573		head: PresentHead
574	): CommitSuccess {
575		return Object.freeze({
576			capability: createPreparedCreatorSuccessorAdoption(handle, {
577				activation: completeCreatorSuccessorLiveMaterial(material.activation, head),
578				exactCanonicalProjectionBytes: material.exactCanonicalProjectionBytes,
579				head,
580			}),
581			descriptor,
582			head: Object.freeze({ ...head }),
583			lifecycle: "successor-prepared" as const,
584			ok: true as const,
585			recovery: "active-new" as const,
586		});
587	}
588	
589	function stagedSuccess(
590		handle: object,
591		material: CreatorAdoptionIntentMaterial,
592		descriptor: Readonly<Record<string, unknown>>
593	): StageSuccess {
594		return Object.freeze({
595			capability: createStagedCreatorSuccessorAdoption(handle, { descriptor, intent: material }),
596			descriptor,
597			lifecycle: "successor-staged" as const,
598			ok: true as const,
599			recovery: "pending-old" as const,
600		});
601	}
602	
603	async function stageCreatorSuccessorAdoptionKernel(input: unknown): Promise<CommitFailure | StageSuccess> {
604		const captured = captureInput(input);
605		if (captured === undefined) return failure("malformed-input", "creator adoption stage input is invalid");
606		const facts = resolveCreatorAdoptionFacts<SealedAdoptionFacts>(captured.handle);
607		const material = consumeCreatorAdoptionIntent(captured.intent, captured.handle);
608		if (facts === undefined || material === undefined) {
609			return failure("intent-unavailable", "creator adoption intent is unavailable");
610		}
611		const descriptor = validProjection(material);
612		if (descriptor === undefined) return failure("internal-invariant", "creator successor projection is invalid");
613		const terminal = await authenticatedTerminal(facts, material);
614		if (terminal.kind === "active-new") return failure("stale-head", "creator successor is already published");
615		if (terminal.kind === "stale-head") return failure("stale-head", "creator successor head is stale");
616		if (terminal.kind === "recovery-failed") return failure("recovery-failed", "creator successor recovery failed");
617		if (terminal.kind === "chain-invalid") return failure("chain-invalid", "creator successor chain is invalid");
618		try {
619			await stageCandidate(facts, material);
620		} catch {
621			// A fresh authenticated inspection below is the only authority after an ambiguous write.
622		}
623		const staged = await authenticatedStaged(facts, material);
624		if (staged.kind === "staged") return stagedSuccess(captured.handle, material, descriptor);
625		if (staged.kind === "stale-head") return failure("stale-head", "creator successor head is stale");
626		if (staged.kind === "chain-invalid") return failure("chain-invalid", "creator successor chain is invalid");
627		if (staged.kind === "recovery-failed") return failure("recovery-failed", "creator successor recovery failed");
628		return failure("pending-old", "creator successor is not durably complete");
629	}
630	
631	async function publishStagedCreatorSuccessorAdoptionKernel(input: unknown): Promise<CommitFailure | PublishSuccess> {
632		const captured = capturePublishInput(input);
633		if (captured === undefined) return failure("malformed-input", "creator adoption publish input is invalid");
634		const facts = resolveCreatorAdoptionFacts<SealedAdoptionFacts>(captured.handle);
635		const staged = consumeStagedCreatorSuccessorAdoption(captured.capability, captured.handle);
636		if (facts === undefined || staged === undefined) {
637			return failure("intent-unavailable", "creator adoption staged capability is unavailable");
638		}
639		let terminal = await authenticatedTerminal(facts, staged.intent);
640		if (terminal.kind === "active-new") return success(captured.handle, staged.intent, staged.descriptor, terminal.head);
641		if (terminal.kind === "stale-head") return failure("stale-head", "creator successor head is stale");
642		if (terminal.kind === "recovery-failed") return failure("recovery-failed", "creator successor recovery failed");
643		if (terminal.kind === "chain-invalid") return failure("chain-invalid", "creator successor chain is invalid");
644		const authenticated = await authenticatedStaged(facts, staged.intent);
645		if (authenticated.kind !== "staged") {
646			return authenticated.kind === "recovery-failed"
647				? failure("recovery-failed", "creator successor recovery failed")
648				: authenticated.kind === "stale-head"
649					? failure("stale-head", "creator successor head is stale")
650					: failure("chain-invalid", "creator successor staged generation is invalid");
651		}
652		try {
653			await publishCandidate(facts, staged.intent);
654		} catch {
655			// A fresh authenticated reopen below is the only authority after an ambiguous CAS.
656		}
657		terminal = await authenticatedTerminal(facts, staged.intent);
658		if (terminal.kind === "active-new") return success(captured.handle, staged.intent, staged.descriptor, terminal.head);
659		if (terminal.kind === "pending-old") return failure("pending-old", "creator successor remains safely pending");
660		if (terminal.kind === "stale-head") return failure("stale-head", "creator successor head is stale");
661		if (terminal.kind === "chain-invalid") return failure("chain-invalid", "creator successor chain is invalid");
662		if (terminal.kind === "recovery-failed") return failure("recovery-failed", "creator successor recovery failed");
663		return failure("storage-failed", "creator successor storage failed");
664	}
665	
666	/**
667	 * Commits a verified creator successor with one durable head comparison-and-swap.
668	 * This retained one-call API does not publish provider freshness and must not
669	 * advance a provider-scoped product room.
670	 * @param input - Genuine close handle and its owner-bound, one-use intent.
671	 * @returns Exact prepared successor or a closed failure.
672	 */
673	export async function commitCreatorSuccessorAdoption(input: unknown): Promise<CommitFailure | CommitSuccess> {
674		const captured = captureInput(input);
675		if (captured === undefined) return failure("malformed-input", "creator adoption commit input is invalid");
676		const facts = resolveCreatorAdoptionFacts<SealedAdoptionFacts>(captured.handle);
677		const material = consumeCreatorAdoptionIntent(captured.intent, captured.handle);
678		if (facts === undefined || material === undefined) {
679			return failure("intent-unavailable", "creator adoption intent is unavailable");
680		}
681		const descriptor = validProjection(material);
682		if (descriptor === undefined) return failure("internal-invariant", "creator successor projection is invalid");
683		let terminal = await authenticatedTerminal(facts, material);
684		if (terminal.kind === "active-new") return success(captured.handle, material, descriptor, terminal.head);
685		if (terminal.kind === "stale-head") return failure("stale-head", "creator successor head is stale");
686		if (terminal.kind === "recovery-failed") return failure("recovery-failed", "creator successor recovery failed");
687		if (terminal.kind === "chain-invalid") return failure("chain-invalid", "creator successor chain is invalid");
688		let stageRequestFailed = false;
689		try {
690			await stageCandidate(facts, material);
691		} catch {
692			stageRequestFailed = true;
693			// A fresh authenticated reopen below is the only authority after an ambiguous write.
694		}
695		const staged = stageRequestFailed ? undefined : await authenticatedStaged(facts, material);
696		if (staged?.kind === "staged") {
697			try {
698				await publishCandidate(facts, material);
699			} catch {
700				// A fresh authenticated reopen below is the only authority after an ambiguous CAS.
701			}
702		}
703		terminal = await authenticatedTerminal(facts, material);
704		if (terminal.kind === "active-new") return success(captured.handle, material, descriptor, terminal.head);
705		if (terminal.kind === "pending-old") return failure("pending-old", "creator successor remains safely pending");
706		if (terminal.kind === "stale-head") return failure("stale-head", "creator successor head is stale");
707		if (terminal.kind === "chain-invalid") return failure("chain-invalid", "creator successor chain is invalid");
708		if (terminal.kind === "recovery-failed") return failure("recovery-failed", "creator successor recovery failed");
709		return failure("storage-failed", "creator successor storage failed");
710	}
711	
712	if (!installCreatorAdoptionStage(stageCreatorSuccessorAdoptionKernel)) {
713		throw new TypeError("creator adoption stage owner was already installed");
714	}
715	if (!installCreatorAdoptionPublish(publishStagedCreatorSuccessorAdoptionKernel)) {
716		throw new TypeError("creator adoption publish owner was already installed");
717	}
